PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS franchises(id INTEGER PRIMARY KEY,name TEXT NOT NULL,region TEXT NOT NULL,owner TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS outlets(id INTEGER PRIMARY KEY,franchise_id INTEGER NOT NULL REFERENCES franchises(id),name TEXT NOT NULL,region TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'active');
CREATE TABLE IF NOT EXISTS sales(id INTEGER PRIMARY KEY,outlet_id INTEGER NOT NULL REFERENCES outlets(id),date TEXT NOT NULL,revenue REAL NOT NULL CHECK(revenue>=0),transactions INTEGER NOT NULL CHECK(transactions>=0),cost REAL NOT NULL CHECK(cost>=0),UNIQUE(outlet_id,date));
CREATE TABLE IF NOT EXISTS inventory(id INTEGER PRIMARY KEY,outlet_id INTEGER NOT NULL REFERENCES outlets(id),product TEXT NOT NULL,quantity REAL NOT NULL CHECK(quantity>=0),reorder_level REAL NOT NULL CHECK(reorder_level>=0),lead_days INTEGER NOT NULL CHECK(lead_days>=1),unit_cost REAL NOT NULL CHECK(unit_cost>=0),expiry_date TEXT NOT NULL,UNIQUE(outlet_id,product));
CREATE TABLE IF NOT EXISTS movements(id INTEGER PRIMARY KEY,inventory_id INTEGER NOT NULL REFERENCES inventory(id),date TEXT NOT NULL,used REAL NOT NULL CHECK(used>=0),wasted REAL NOT NULL CHECK(wasted>=0),UNIQUE(inventory_id,date));
CREATE TABLE IF NOT EXISTS staff(id INTEGER PRIMARY KEY,outlet_id INTEGER NOT NULL REFERENCES outlets(id),name TEXT NOT NULL,role TEXT NOT NULL,scheduled_hours REAL NOT NULL CHECK(scheduled_hours>0),worked_hours REAL NOT NULL CHECK(worked_hours>=0),orders INTEGER NOT NULL CHECK(orders>=0),shift TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS campaigns(id INTEGER PRIMARY KEY,outlet_id INTEGER NOT NULL REFERENCES outlets(id),name TEXT NOT NULL,spend REAL NOT NULL CHECK(spend>=0),attributed_revenue REAL NOT NULL CHECK(attributed_revenue>=0),gross_margin REAL NOT NULL CHECK(gross_margin>=0 AND gross_margin<=1),impressions INTEGER NOT NULL CHECK(impressions>=0),clicks INTEGER NOT NULL CHECK(clicks>=0),conversions INTEGER NOT NULL CHECK(conversions>=0),status TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audits(id INTEGER PRIMARY KEY,outlet_id INTEGER NOT NULL REFERENCES outlets(id),date TEXT NOT NULL,category TEXT NOT NULL,score REAL NOT NULL CHECK(score>=0 AND score<=100),finding TEXT NOT NULL,critical INTEGER NOT NULL CHECK(critical IN (0,1)));
CREATE TABLE IF NOT EXISTS runs(id INTEGER PRIMARY KEY,started_at TEXT NOT NULL,finished_at TEXT,status TEXT NOT NULL,summary TEXT);
CREATE TABLE IF NOT EXISTS alerts(id INTEGER PRIMARY KEY,outlet_id INTEGER NOT NULL REFERENCES outlets(id),agent TEXT NOT NULL,alert_key TEXT NOT NULL UNIQUE,severity TEXT NOT NULL,message TEXT NOT NULL,recommendation TEXT NOT NULL,created_at TEXT NOT NULL,last_seen TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open',owner TEXT NOT NULL DEFAULT '',due_date TEXT,notes TEXT NOT NULL DEFAULT '',resolved_at TEXT);
CREATE TABLE IF NOT EXISTS notifications(id INTEGER PRIMARY KEY,alert_id INTEGER NOT NULL REFERENCES alerts(id),channel TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',attempts INTEGER NOT NULL DEFAULT 0,error TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL,sent_at TEXT,UNIQUE(alert_id,channel));
CREATE TABLE IF NOT EXISTS activity(id INTEGER PRIMARY KEY,at TEXT NOT NULL,action TEXT NOT NULL,detail TEXT NOT NULL);
